using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static void LowCost(){
  var all=catalog.Deckable(catalog.Pool("classic-2014"));Check(all.Where(c=>c.Cost>=1&&c.Cost<=2&&c.CardClass!="HUNTER").All(matchRules.Supports),"All non-Hunter one and two mana cards supported");Check(LowCostRules.CardIds.All(id=>catalog.Card("VAN_"+id).CardClass=="NEUTRAL"),"This batch registers neutral cards only");
  var g=MatchFixture("ROGUE");var deckhand=g.Summon(0,"VAN_CS2_146");Check(!g.HasCharge(deckhand)&&g.CanAttack(0,deckhand)!=null,"Deckhand has no charge without weapon");g.HeroPower(0);Check(g.HasCharge(deckhand)&&g.CanAttack(0,deckhand)==null,"Equipping weapon dynamically enables Deckhand charge");g.BreakWeapon(0);Check(!g.HasCharge(deckhand)&&g.CanAttack(0,deckhand)!=null,"Breaking weapon immediately removes charge");g.EquipRaw(0,"GAME_DAGGER",1,2,false);g.Silence(new MatchTarget(0,deckhand.Id));Check(!g.HasCharge(deckhand),"Silence disables Deckhand intrinsic charge condition");
  g=MatchFixture();var ward=g.Summon(0,"VAN_EX1_001");var enemyWard=g.Summon(1,"VAN_EX1_001");g.Players[0].Health=20;g.Heal(new MatchTarget(0),2);Check(g.AttackValue(ward)==3&&g.AttackValue(enemyWard)==3,"Both Lightwardens grow on actual hero healing");var body=g.Summon(1,"VAN_CS2_182");g.Damage(new MatchTarget(1,body.Id),1);g.Heal(new MatchTarget(1,body.Id),8);Check(g.AttackValue(ward)==5&&g.AttackValue(enemyWard)==5,"Both Lightwardens grow on enemy minion healing");g.Heal(new MatchTarget(1,body.Id),8);Check(g.AttackValue(ward)==5,"Overheal produces no Lightwarden growth");g.Silence(new MatchTarget(0,ward.Id));g.Players[1].Health=20;g.Heal(new MatchTarget(1),1);Check(g.AttackValue(ward)==1&&g.AttackValue(enemyWard)==7,"Silence clears and stops Lightwarden bonus");
  g=MatchFixture();body=g.Summon(0,"VAN_CS2_182");g.Buff(new MatchTarget(0,body.Id),2,2);g.Play(0,Hand(g,"EX1_049"),new MatchTarget(0,body.Id));Check(g.Players[0].Board.Single().CardId=="VAN_EX1_049"&&g.Players[0].Hand.Single().CardId=="VAN_CS2_182"&&g.Players[0].Hand.Single().CostAdjustment==0,"Young Brewmaster returns plain friendly hand card");
  g=MatchFixture();body=g.Summon(0,"VAN_CS2_182");int h=Hand(g,"EX1_049");Check(!g.Play(0,h,new MatchTarget(1)).Success&&g.Players[0].Mana==10&&g.Players[0].Board.Count==1,"Brewmaster illegal target is atomic");
  g=MatchFixture();var addict=g.Summon(0,"VAN_EX1_055");g.Play(0,Hand(g,"GAME_COIN"));g.Play(0,Hand(g,"CS1_130"),new MatchTarget(1));Check(g.AttackValue(addict)==5,"Mana Addict gains two for each successful spell cast");g.EndTurn();Check(g.AttackValue(addict)==1&&addict.TempAttack==0,"Mana Addict bonus expires at end of turn");
  g=MatchFixture();body=g.Summon(1,"VAN_CS2_182");body.DamageTaken=2;g.Play(0,Hand(g,"EX1_059"),new MatchTarget(1,body.Id));Check(body.Health==4&&body.MaxHealth==4&&g.AttackValue(body)==3,"Alchemist swaps current attack and injured current health");
  g=MatchFixture();body=g.Summon(1,"VAN_CS2_mirror");g.Play(0,Hand(g,"EX1_059"),new MatchTarget(1,body.Id));Check(g.Players[1].Board.Count==0&&g.Graveyard.Any(e=>e.CardId=="VAN_CS2_mirror"),"Swapping zero attack kills minion");
  g=MatchFixture();var keeper=g.Summon(0,"VAN_EX1_080");var enemyKeeper=g.Summon(1,"VAN_EX1_080");g.Play(0,Hand(g,"EX1_287"));Check(g.AttackValue(keeper)==2&&keeper.MaxHealth==3&&g.AttackValue(enemyKeeper)==2,"Both Secretkeepers grow on played secret");h=Hand(g,"EX1_287");g.Players[0].Mana=10;g.Play(0,h);Check(g.AttackValue(keeper)==2,"Rejected duplicate secret does not trigger Secretkeeper");g.Play(0,Hand(g,"GAME_COIN"));Check(g.AttackValue(keeper)==2,"Non-secret spell does not grow Secretkeeper");
  g=MatchFixture();g.Summon(0,"VAN_EX1_563");g.Summon(0,"VAN_EX1_350");int healthBefore=g.Players[0].Health+g.Players[1].Health+g.Players[0].Board.Sum(u=>u.Health);g.Play(0,Hand(g,"EX1_082"));var bomber=g.Players[0].Board.Single(u=>u.CardId=="VAN_EX1_082");int remaining=g.Players[0].Health+g.Players[1].Health+g.Players[0].Board.Where(u=>u.Id!=bomber.Id).Sum(u=>u.Health);Check(healthBefore-remaining==3&&bomber.Health==2,"Bomber deals three one-damage battlecry hits, excludes itself and ignores spell modifiers");
  g=MatchFixture();g.Players[0].Deck.Clear();g.Players[0].Deck.AddRange(new[]{"VAN_CS2_182","VAN_NEW1_018","VAN_CS2_231"});g.Play(0,Hand(g,"NEW1_016"));Check(g.Players[0].Hand.Single().CardId=="VAN_NEW1_018"&&g.Players[0].Deck.SequenceEqual(new[]{"VAN_CS2_182","VAN_CS2_231"}),"Parrot draws matching Pirate without disturbing remaining deck order");
  g=MatchFixture();g.Players[0].Deck.Clear();g.Play(0,Hand(g,"NEW1_016"));Check(g.Players[0].Hand.Count==0&&g.Players[0].Fatigue==0,"No Pirate yields no card and no fatigue");
  g=MatchFixture();g.EquipRaw(0,"GAME_BLOOD_FURY",3,8,false);g.Players[0].TempAttack=4;g.Play(0,Hand(g,"NEW1_018"));body=g.Players[0].Board.Single();Check(g.AttackValue(body)==5,"Raider uses weapon attack, excludes temporary hero attack");g.BreakWeapon(0);Check(g.AttackValue(body)==5,"Raider battlecry buff stays after weapon breaks");
  g=MatchFixture();var knife=g.Summon(0,"VAN_NEW1_019");g.Play(0,Hand(g,"EX1_506"));Check(g.Players[1].Health==28&&g.Players[0].Board.Count==3,"Knife triggers once each for played body and battlecry token");g.Transform(new MatchTarget(0,g.Players[0].Board[1].Id),"GAME_FROG");Check(g.Players[1].Health==28,"Transformation produces no summon-trigger dagger");g.Silence(new MatchTarget(0,knife.Id));g.Summon(0,"VAN_CS2_182");Check(g.Players[1].Health==28,"Silenced Knife stops throwing");
  g=MatchFixture();knife=g.Summon(0,"VAN_NEW1_019");g.Play(0,Hand(g,"EX1_049"),new MatchTarget(0,knife.Id));Check(g.Players[1].Health==30,"Brewmaster battlecry returns Knife before post-summon trigger");
  g=MatchFixture();var pyro=g.Summon(0,"VAN_NEW1_020");body=g.Summon(1,"VAN_CS2_182");g.Play(0,Hand(g,"CS2_004"),new MatchTarget(0,pyro.Id));Check(pyro.MaxHealth==4&&pyro.Health==3&&body.Health==4,"Pyromancer fires after shield buff, not before");Check(g.Players[0].Health==30&&g.Players[1].Health==30,"Pyromancer only hits minions");g.Play(0,Hand(g,"GAME_COIN"));Check(pyro.Health==2&&body.Health==3,"Coin activates Pyromancer after resolution");
  g=MatchFixture("MAGE","MAGE");g.Play(0,Hand(g,"EX1_287"));g.EndTurn();pyro=g.Summon(1,"VAN_NEW1_020");g.Play(1,Hand(g,"GAME_COIN",1));Check(pyro.Health==2,"Countered spell does not activate after-spell Pyromancer");
  g=MatchFixture();g.EquipRaw(1,"GAME_DAGGER",1,2,false);g.Play(0,Hand(g,"NEW1_025"));Check(g.Players[1].WeaponDurability==1,"Corsair removes one enemy durability");g.Play(0,Hand(g,"NEW1_025"));Check(g.Players[1].WeaponId==null&&g.Graveyard.Count(e=>e.Reason==GraveyardReason.WeaponDestroyed)==1,"Corsair breaks weapon once at zero durability");
  var folder=Path.Combine(Environment.CurrentDirectory,"previews");Directory.CreateDirectory(folder);JsonData.Write(Path.Combine(folder,"match-rule-coverage.json"),new{SupportedCards=all.Count(matchRules.Supports),TotalCards=all.Count,Cards=all.Select(c=>new{Id=c.Id,Name=c.Name,Supported=matchRules.Supports(c)}).ToArray(),Scope="All classic cards; non-Hunter one/two mana completed"});
 }
}
